Q: How to extend class based off of template parameters? A: <p>Unless you need something more complicated I'd use a simple view:</p>
<pre><code>template &lt;typename T&gt;
struct VectorViewXY {
    Vector&lt;T,2&gt;&amp; base;
    T&amp; x() {return base.values[0];}
    T&amp; y() {return base.values[1];}
};

int main() {
    Vector&lt;double,2&gt; a;
    VectorViewXY xy(a);
    xy.x() = 42;
    xy.y() = 0;


}
</code></pre>
<p><a href="https://godbolt.org/z/czEGMf67v" rel="nofollow noreferrer">Live Demo</a></p>
<p>Note that your <code>failSafeVector</code> is superfluous. Here:</p>
<pre><code>Vector operator+(const Vector &amp;rhs) {
</code></pre>
<p><code>const Vector &amp;rhs</code> is shorthand for <code>Vector&lt;T,N&gt;</code>, ie a <code>Vector&lt;double,42&gt;</code> has a <code>operator+</code> with signature <code>Vector&lt;double,42&gt; operator+(const Vector&lt;double,42&gt;&amp;)</code>. It accepts no other instantations of the class template.</p>
<p>If you want to have methods accept other Vectors you can make them member templates. For example to accept different <code>T</code> (but same size):</p>
<pre><code>template &lt;typename T,size_t size&gt;
struct Vector {
    template &lt;typename U&gt;
    Vector&lt;std::common_type_t&lt;T,U&gt;,size&gt; operator+(const Vector&lt;U,size&gt;&amp;);
};
</code></pre>

Q: Read Key presses in C; ex.: Arrow keys, Enter key A: <p>Here's a hack based on my other answer here: <a href="https://stackoverflow.com/a/70979820/4561887">Capture characters from standard input without waiting for enter to be pressed</a>. I use a bash system call in C or C++ to read and parse arrow key presses. Arrow key presses come in as 3 chars, so I parse 3 chars at a time and figure out which arrow key it was.</p>
<p>There is no need to ever press <kbd>Enter</kbd> (which is unlike when using the <code>getc()</code> command, which will only return when you press <kbd>Enter</kbd>). The arrow key presses are detected immediately after you press them.</p>
<p><a href="https://github.com/ElectricRCAircraftGuy/eRCaGuy_hello_world/blob/master/c/read_system_call_via_pipe__arrow_keypresses.c" rel="nofollow noreferrer"><strong>read_system_call_via_pipe__arrow_keypresses.c</strong></a>:</p>
<pre class="lang-c prettyprint-override"><code>#include &lt;stdbool.h&gt; // For `true` (`1`) and `false` (`0`) macros in C
#include &lt;stdint.h&gt;  // For `uint8_t`, `int8_t`, etc.
#include &lt;stdio.h&gt;   // For `printf()`
#include &lt;stdlib.h&gt;

#define BUFSIZE 32

typedef enum arrowKey_e
{
    ARROWKEY_UNKNOWN = 0,
    ARROWKEY_UP,
    ARROWKEY_DOWN,
    ARROWKEY_LEFT,
    ARROWKEY_RIGHT,
} arrowKey_t;

// Modeled after my answer here: https://stackoverflow.com/a/54728664/4561887
const char* arrowKeyGetName(arrowKey_t arrowKey)
{
    const char* arrowKeyName = &quot;TBD&quot;;

    switch (arrowKey)
    {
        case ARROWKEY_UNKNOWN:
            arrowKeyName = &quot;ARROWKEY_UNKNOWN&quot;;
            break;
        case ARROWKEY_UP:
            arrowKeyName = &quot;ARROWKEY_UP&quot;;
            break;
        case ARROWKEY_DOWN:
            arrowKeyName = &quot;ARROWKEY_DOWN&quot;;
            break;
        case ARROWKEY_LEFT:
            arrowKeyName = &quot;ARROWKEY_LEFT&quot;;
            break;
        case ARROWKEY_RIGHT:
            arrowKeyName = &quot;ARROWKEY_RIGHT&quot;;
            break;
    }

    return arrowKeyName;
}

// Read a keyboard key press and return the character pressed, or a negative
// number in the event of an error.
// NB: for help reading output from system calls, see here:
//  1. https://stackoverflow.com/a/28971647/4561887
//  2. https://stackoverflow.com/a/18297075/4561887
arrowKey_t readArrowKeyPress()
{
    arrowKey_t arrowKeyPressed = ARROWKEY_UNKNOWN;

    // This bash cmd is from my answer here:
    // https://stackoverflow.com/a/70979348/4561887
    // `-n3` here means to read 3 chars at once, since an arrow key press
    // comes in as 3 chars.
    // The `-t .01` forces a timeout of that many seconds, which means the loop
    // interval will be this fast.
    const char* cmd = &quot;bash -c 'read -s -t .1 -n3 c &amp;&amp; printf \&quot;%s\&quot; \&quot;$c\&quot;'&quot;;
    FILE *fp = popen(cmd, &quot;r&quot;);
    if (fp == NULL)
    {
        printf(&quot;\nError opening pipe!\n&quot;);
        return arrowKeyPressed;
    }

    char buf[BUFSIZE] = {0};
    char* retval1 = fgets(buf, BUFSIZE, fp);
    if (retval1 == NULL)
    {
        // printf(&quot;\nFailed to read cmd response.\n&quot;);
        // Timeout occured; just exit.
        return arrowKeyPressed;
    }

    // See meaning of this return value here:
    // https://stackoverflow.com/questions/43116/how-can-i-run-an-external-program-from-c-and-parse-its-output/28971647#comment60311936_28971647
    int retval2 = pclose(fp);
    if (retval2 == -1)
    {
        printf(&quot;\nError obtaining the cmd's exit status code.\n&quot;);
        return arrowKeyPressed;
    }
    else if (retval2 != 0)
    {
        printf(&quot;\nCommand exited with exit status code %i.\n&quot;, retval2);
        return arrowKeyPressed;
    }

    // Map the readings to arrow keys
    if ((buf[0] == 27) &amp;&amp; (buf[1] == 91) &amp;&amp; (buf[2] == 65))
    {
        arrowKeyPressed = ARROWKEY_UP;
    }
    else if ((buf[0] == 27) &amp;&amp; (buf[1] == 91) &amp;&amp; (buf[2] == 66))
    {
        arrowKeyPressed = ARROWKEY_DOWN;
    }
    else if ((buf[0] == 27) &amp;&amp; (buf[1] == 91) &amp;&amp; (buf[2] == 67))
    {
        arrowKeyPressed = ARROWKEY_RIGHT;
    }
    else if ((buf[0] == 27) &amp;&amp; (buf[1] == 91) &amp;&amp; (buf[2] == 68))
    {
        arrowKeyPressed = ARROWKEY_LEFT;
    }

    return arrowKeyPressed;
}

// int main(int argc, char *argv[])  // alternative prototype
int main()
{
    printf(&quot;Press any arrow key. Press Ctrl + C to quit.\n&quot;);
    fflush(stdout);

    while (true)
    {
        arrowKey_t arrowKeyPressed = readArrowKeyPress();
        if (arrowKeyPressed == ARROWKEY_UNKNOWN)
        {
            continue;
        }
        printf(&quot;Key pressed = %s\n&quot;, arrowKeyGetName(arrowKeyPressed));
    }

    return 0;
}
</code></pre>
